module strcount_pipe (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire flush,
    input wire [7:0] ch,
    output wire [5:0] o_cnt
);
    parameter [7:0] TARGET = 8'h61;

    reg [5:0] total = 6'd0;   // characters accepted
    reg [5:0] cnt   = 6'd0;   // committed occurrences of TARGET
    reg       st_valid = 1'b0; // staged character present
    reg       st_match = 1'b0; // staged character equals TARGET
    reg [2:0] pend = 3'd0;    // occurrences held locally, not yet merged into cnt

    wire full   = (total == 6'd63);
    wire accept = ce && !full;
    wire retire = st_valid && st_match;   // staged match leaves the stage this cycle
    wire dump   = (pend == 3'd3);         // local accumulator full: merge a block of 4

    always @(posedge clk)
        if (rst) begin
            total    <= 6'd0;
            cnt      <= 6'd0;
            st_valid <= 1'b0;
            st_match <= 1'b0;
            pend     <= 3'd0;
        end else if (accept) begin
            total    <= total + 6'd1;
            st_valid <= 1'b1;
            st_match <= (ch == TARGET);
            if (retire) begin
                if (dump) begin
                    cnt  <= cnt + 6'd4;
                    pend <= 3'd0;
                end else
                    pend <= pend + 3'd1;
            end
        end else if (flush && st_valid) begin
            st_valid <= 1'b0;
            if (st_match) begin
                if (dump) begin
                    cnt  <= cnt + 6'd4;
                    pend <= 3'd0;
                end else
                    pend <= pend + 3'd1;
            end
        end

    assign o_cnt = cnt + {3'd0, pend};

    always @(*)
        if (!st_valid)
            assert (cnt <= total);
endmodule

