module token_bucket_ledger (
    input  wire       clk,
    input  wire       rst,
    input  wire       drip_en,
    input  wire       grant_req,
    output wire       grant,
    output wire       dry
);
    localparam [3:0] CAP = 4'd8;

    // bucket level
    reg [3:0] tokens = 4'd0;
    // free-running mod-16 ledgers of every accepted drip and every issued grant
    reg [3:0] drips  = 4'd0;
    reg [3:0] grants = 4'd0;

   // accepted drips are shaped: a credit spends four cycles in flight before it
   // actually lands in the bucket, at most one credit per stage
   reg        drip_s1 = 1'b0;
   reg        drip_s2 = 1'b0;
   reg        drip_s3 = 1'b0;
   reg        drip_s4 = 1'b0;

   wire [3:0] in_flight = {3'd0, drip_s1} + {3'd0, drip_s2}
                        + {3'd0, drip_s3} + {3'd0, drip_s4};


   // credits already promised to the bucket count against the cap at accept time
   wire do_drip  = drip_en   && ((tokens + in_flight) < CAP);
    wire do_grant = grant_req && (tokens != 4'd0);
   wire land     = drip_s4;

    assign grant = do_grant;
    assign dry   = (tokens == 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            tokens <= 4'd0;
            drips  <= 4'd0;
            grants <= 4'd0;
           drip_s1 <= 1'b0;
           drip_s2 <= 1'b0;
           drip_s3 <= 1'b0;
           drip_s4 <= 1'b0;
        end else begin
           if (land && !do_grant)
                tokens <= tokens + 4'd1;
           else if (!land && do_grant)
                tokens <= tokens - 4'd1;

           drip_s1 <= do_drip;
           drip_s2 <= drip_s1;
           drip_s3 <= drip_s2;
           drip_s4 <= drip_s3;

            if (do_drip)
                drips <= drips + 4'd1;
            if (do_grant)
                grants <= grants + 4'd1;
        end
    end

    // P: whenever the two ledgers agree, the bucket must be empty
    always @(posedge clk)
        if (drips == grants)
            assert (tokens == 4'd0);
endmodule

