        if (rst) begin
            sp        <= 3'd0;
            items     <= 3'd0;
            top_valid <= 1'b0;
full      <= 1'b0;
empty     <= 1'b1;
push_cnt  <= 3'd0;
pop_cnt   <= 3'd0;
end else begin
    if (do_push) begin
        sp       <= sp + 3'd1;
        items    <= items + 3'd1;
        push_cnt <= push_cnt + 3'd1;
    end else if (do_pop) begin
        sp       <= sp - 3'd1;
        items    <= items - 3'd1;
        pop_cnt  <= pop_cnt + 3'd1;
