wire [2:0] nlevel = ncount + {2'b0, nstage};

    always @(posedge clk) begin
        if (rst) begin
            wptr <= 2'd0; rptr <= 2'd0; count <= 3'd0;
            empty_r <= 1'b1; full_r <= 1'b0;
stage_v <= 1'b0;
        end else begin
            wptr <= nw;
            rptr <= nr;
            empty_r <= (nw == nr) && (do_pop  || (empty_r && !do_push));
full_r  <= (nlevel == 3'd4);
count   <= ncount;
stage_v <= nstage;
        end
    end

    always @(posedge clk)
        if (empty_r)
            assert (!full_r);
endmodule

