// Packet-capture sensor credit window.
// TOTAL = 8 stream credits.  A burst send spends 3 credits (they become
// "outstanding" bytes in flight); the collector returns exactly one credit
// per enabled cycle while anything is outstanding.  A deadline register is
// reloaded on every accepted burst and counts down otherwise; it must never
// expire while credits are still outstanding.
module credit_window (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire       i_send,    // producer requests a burst
    output wire       o_busy
);
    reg [3:0] avail;   // credits held by the sensor
    reg [3:0] outst;   // credits outstanding (in flight)
    reg [3:0] timer;   // completion deadline countdown
    reg       armed;   // sticky: set the first time a burst is accepted

   // Adaptive window: grow the credit window while the producer is stalled,
   // reclaim a credit once the link has been quiet for a while.
   localparam [3:0] POOL_MIN = 4'd3;
   localparam [3:0] POOL_MAX = 4'd10;
   reg [3:0] pool;      // credits belonging to the window (held + in flight)
   reg [1:0] idle_cnt;  // consecutive quiet cycles, saturating at 3

    initial avail = 4'd8;
    initial outst = 4'd0;
    initial timer = 4'd0;
    initial armed = 1'b0;
   initial pool = 4'd8;
   initial idle_cnt = 2'd0;

    wire send_ok = i_send && (avail >= 4'd3);
    wire retire  = (outst != 4'd0);
   wire stalled = i_send && (avail < 4'd3);
   wire grow    = stalled && (pool != POOL_MAX);
   wire shrink  = (idle_cnt == 2'd3) && !i_send && (pool != POOL_MIN);

    assign o_busy = (outst != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            avail <= 4'd8;
            outst <= 4'd0;
            timer <= 4'd0;
            armed <= 1'b0;
           pool     <= 4'd8;
           idle_cnt <= 2'd0;
        end else if (i_ce) begin
            if (send_ok) begin
                // spend three credits, one may come back the same cycle
                avail <= avail - 4'd3 + (retire ? 4'd1 : 4'd0);
                outst <= outst + 4'd3 - (retire ? 4'd1 : 4'd0);
               timer <= pool + 4'd1;   // deadline tracks the window size
                armed <= 1'b1;          // sticky arm
               idle_cnt <= 2'd0;
            end else if (retire) begin
               avail <= avail + 4'd1 + (grow ? 4'd1 : 4'd0);
                outst <= outst - 4'd1;
                if (timer != 4'd0)
                    timer <= timer - 4'd1;
               if (grow)
                   pool <= pool + 4'd1;
               idle_cnt <= 2'd0;
            end else begin
                if (timer != 4'd0)
                    timer <= timer - 4'd1;
               if (grow) begin
                   avail <= avail + 4'd1;
                   pool  <= pool  + 4'd1;
               end else if (shrink) begin
                   avail <= avail - 4'd1;
                   pool  <= pool  - 4'd1;
               end
               if (i_send)
                   idle_cnt <= 2'd0;
               else if (idle_cnt != 2'd3)
                   idle_cnt <= idle_cnt + 2'd1;
            end
        end
    end

    // Bounded response (safety form), scoped after the first accepted burst:
    // the deadline never expires while credits are still outstanding.
    always @(*)
        assert (!armed || !((timer == 4'd0) && (outst != 4'd0)));
endmodule
